@router.get("")
def get_vessels():
    """
    Returns normalized list of all contextual maritime vessels with their
    latest AIS position and historical track coordinates for polyline rendering.
    """
    normalized = []
    for v in VESSELS_DATA:
        # Step 4 normalized format
        positions = [
            {
                "lat": r["lat"],
                "lng": r["lng"],
                "timestamp": v["trackStart"],
                "speed": v["speed"],
                "course": v["heading"],
            }
            for r in v["routes"]
        ]
        
        normalized.append({
            "vesselId": v["id"],
            "id": v["id"],
            "name": v["name"],
            "callsign": v["callsign"],
            "imo": v["imo"],
            "mmsi": v["mmsi"],
            "flag": v["flag"],
            "vesselType": v["vesselType"],
            "type": "vessel",
            "currentPosition": {
                "lat": v["latitude"],
                "lng": v["longitude"],
                "timestamp": v["lastUpdate"],
            },
            "latitude": v["latitude"],
            "longitude": v["longitude"],
            "speed": v["speed"],
            "heading": v["heading"],
            "status": v["status"],
            "origin": v["origin"],
            "destination": v["destination"],
            "eta": v["eta"],
            "draftMeters": v["draftMeters"],
            "beamMeters": v["beamMeters"],
            "lastUpdate": v["lastUpdate"],
            "positions": positions,
            "routeCoordinates": v["routes"],
            "trackPointsCount": len(v["routes"]),
            "trackStart": v["trackStart"],
            "trackEnd": v["trackEnd"],
            "dataSource": "Global Fishing Watch AIS",
            "isSimulatedDemo": False,
        })
    return normalized
